def text(description, example="Exemplo", **kw):
    return dict(type="string", description=description, examples=[example], **kw)

def uid(description="Identificador interno UUID."):
    return text(description, UUID, format="uuid")

def timestamp(description="Instante em UTC; apresentação no fuso da interface."):
    return text(description, NOW, format="date-time")

def date(description="Data civil no formato AAAA-MM-DD, sem conversão de fuso."):
    return text(description, "1990-11-15", format="date")

def integer(description, example=1, minimum=0, **kw):
    return dict(type="integer", description=description, minimum=minimum, examples=[example], **kw)

def number(description, example=1.0, minimum=0, **kw):
    return dict(type="number", description=description, minimum=minimum, examples=[example], **kw)

def boolean(description, example=False):
    return dict(type="boolean", description=description, examples=[example])

def enum(description, values, example=None):
    return text(description, example or values[0], enum=values)

def ref(name, description=None):
    out = {"$ref": f"#/components/schemas/{name}"}
    if description:
        out["description"] = description
    return out

def nullable(schema):
    return {"anyOf": [schema, {"type": "null"}], "description": schema.get("description", "Valor opcional; null significa ausência.")}

def array(schema, description="Lista de valores.", minimum=0, maximum=100):
    return dict(type="array", items=schema, minItems=minimum, maxItems=maximum, description=description)

def obj(properties, required=(), description=None, **kw):
    out = dict(type="object", additionalProperties=False, properties=properties, **kw)
    if required:
        out["required"] = list(required)
    if description:
        out["description"] = description
    return out

def schema(name, properties, required=(), description=None, **kw):
    SCHEMAS[name] = obj(properties, required, description or name, **kw)
    return name

def resolve(s):
    if "$ref" in s:
        return SCHEMAS[s["$ref"].rsplit("/", 1)[1]]
    return s

def example(s, seen=()):
    """Exemplos estruturais determinísticos, com valores fictícios e revisões explícitas."""
    if "$ref" in s:
        name = s["$ref"].rsplit("/", 1)[1]
        assert name not in seen, f"Referência cíclica sem exemplo explícito: {name}"
        return example(SCHEMAS[name], (*seen, name))
    if "examples" in s:
        return copy.deepcopy(s["examples"][0])
    if "const" in s:
        return copy.deepcopy(s["const"])
    if "enum" in s:
        return copy.deepcopy(s["enum"][0])
    # Objetos com oneOf de restrições continuam usando properties, salvo exemplo explícito.
    if s.get("type") == "object":
        return {k: example(v, seen) for k, v in s.get("properties", {}).items()}
    for key in ["oneOf", "anyOf"]:
        if key in s:
            return example(s[key][0], seen)
    if s.get("type") == "array":
        return [example(s["items"], seen) for _ in range(max(1, s.get("minItems", 0)))]
    if s.get("type") == "string":
        return "<bytes-do-arquivo>" if s.get("format") == "binary" else "exemplo"
    if s.get("type") == "integer":
        return max(1, s.get("minimum", 0))
    if s.get("type") == "number":
        return max(1.0, s.get("minimum", 0))
    if s.get("type") == "boolean":
        return False
    if s.get("type") == "null":
        return None
    raise ValueError(s)


def model(name, properties, required=(), description="", **kw):
    return schema(name, properties, required, description or name, **kw)


def versioned(name, properties, required=(), description=""):
    return model(name, {"id": uid(), "versao": integer("Versão informativa do agregado; usar o ETag opaco retornado, sem montá-lo no frontend.", 1, 1), "etag": text("Token de edição já disponível também em listas e comparações; usar literalmente em If-Match.", '"edicao-1"'), **properties}, ["id", "versao", "etag", *required], description)


def clone_fields(name):
    return copy.deepcopy(SCHEMAS[name]["properties"])


