def param(name, kind, description, required=False, where="query"):
    return {"name": name, "in": where, "required": required, "description": description, "schema": kind}


PAG = [param("limite", integer("Itens por página, default 25.", 25, 1, maximum=100), "Limite, máximo 100."), param("cursor", text("Cursor opaco da mesma consulta.", "cursor-exemplo"), "Retomar a página sem refazer consultas por item."), param("incluirTotal", boolean("Total autorizado."), "Default false.")]
DATE = {"name": "data", "in": "query", "required": False, "description": "FiltroData codificado como JSON; a rota declara o campo temporal.", "content": {"application/json": {"schema": ref("FiltroData")}}}
IF_MATCH = param("If-Match", text("ETag opaco recebido, nunca calculado pelo frontend.", '"edicao-1"', pattern='^"[^"\r\n]+"$'), "Versão do agregado/item especificado. 428 ausente, 412 desatualizado; não aceitar *.", True, "header")
IDEM = param("Idempotency-Key", text("Chave por intenção de gravação, reaproveitada só em retry do mesmo corpo.", "22222222-2222-4222-8222-222222222222", minLength=16, maxLength=200), "Mesma identidade+rota+chave+corpo não repete efeitos. Corpo alterado usa nova chave.", True, "header")
CSRF = param("X-CSRF-Token", text("Token entregue em login ou GET /app.", "csrf-exemplo"), "Obrigatório nas chamadas autenticadas não GET; cookie HttpOnly é enviado automaticamente pelo navegador.", True, "header")
ERRORS = {400: "Sintaxe inválida.", 401: "Sessão ausente, expirada ou revogada.", 403: "Operação/campo sem permissão.", 404: "Recurso inexistente ou fora do alcance.", 409: "Conflito de negócio/duplicidade/dependência/estado; o formulário inteiro não é parcialmente salvo.", 410: "Upload, operação ou documento temporário expirado; link revogado/encerrado.", 412: "Versão de edição/revisão desatualizada; preservar rascunho e comparar.", 413: "Limite de payload/arquivo/lote excedido.", 415: "Mídia não suportada.", 422: "Campos/combinações inválidos, com caminhos para o formulário.", 428: "If-Match obrigatório não informado.", 429: "Limite de tentativas/requisições excedido.", 500: "Falha interna sem detalhes sensíveis.", 503: "Dependência temporariamente indisponível."}


def op(method, path, module, screen, action, description, *, body=None, result=None, status=200, permission="", params=(), match=False, public=False, read_post=False, multipart=False, binary=None, tech=False, security=None, etag=False, steps=()):
    method = method.lower()
    target = TECH_PATHS if tech else PATHS
    assert method not in target.get(path, {}), (method, path)
    TAGS.setdefault(module, {"name": module, "description": "Operações necessárias às telas de " + module + "."})
    parameters = []
    for name in re.findall(r"\{([^}]+)\}", path):
        typ = enum("Catálogo com editor real.", ["classificacoes", "servicos", "categorias"]) if name == "catalogo" else (text("Token público opaco.", "identificador-publico-opaco", minLength=24) if name == "token" else uid())
        parameters.append(param(name, typ, typ["description"], True, "path"))
    parameters.extend(copy.deepcopy(list(params)))
    changing = method != "get" and not read_post
    if method != "get" and not public and not tech:
        parameters.append(copy.deepcopy(CSRF))
    idempotency = changing and path not in {"/auth/login", "/auth/logout", "/conta/senha"} and not tech
    if idempotency:
        parameters.append(copy.deepcopy(IDEM))
    if match:
        parameters.append(copy.deepcopy(IF_MATCH))
    if method == "delete":
        parameters.append(param("X-Motivo", text("Justificativa.", "Ação solicitada pelo usuário.", minLength=3), "Motivo auditado; DELETE não recebe corpo.", True, "header"))
    if security is None:
        security = [] if public else [{"sessao": []}]
    success = {"description": "Aceito para processamento; ainda não representa efeito externo concluído." if status == 202 else ("Operação concluída, sem corpo." if status == 204 else "Dados prontos para a tela, no alcance autorizado."), "headers": {"Cache-Control": {"description": "Sem cache público de dados pessoais/QR.", "schema": {"type": "string", "const": "no-store"}}, "X-Request-Id": {"schema": {"type": "string"}}}}
    if result:
        success["content"] = {"application/json": {"schema": ref(result)}}
    if etag:
        success["headers"]["ETag"] = {"description": "Usar este ETag na edição do agregado indicado.", "schema": {"type": "string", "examples": ['"edicao-1"']}}
    if binary:
        success["content"] = {binary: {"schema": {"type": "string", "format": "binary"}}}
    if status == 202 and result == "Operacao":
        success["headers"]["Location"] = {"description": "URI de GET /operacoes/{id} para fallback de acompanhamento.", "schema": {"type": "string"}}
    if changing and not public and not tech:
        success["headers"]["X-Activity-Id"] = {"description": "Atividade do comando agregado, com seus detalhes por campo/vínculo.", "schema": {"type": "string", "format": "uuid"}}
    codes = {400, 422, 429, 500, 503}
    if security:
        codes.add(401)
    if not public:
        codes.add(403)
    if "{" in path:
        codes.add(404)
    if changing:
        codes.add(409)
    if match:
        codes.update({412, 428})
    if multipart:
        codes.update({413, 415})
    if path.startswith(("/publico", "/uploads", "/operacoes", "/arquivos")) or "fus" in path or "reverter" in path:
        codes.add(410)
    responses = {str(status): success, **{str(c): {"$ref": "#/components/responses/Erro" + str(c)} for c in sorted(codes)}}
    operation_id = re.sub(r"[^a-zA-Z0-9]+", "_", method + "_" + path).strip("_")
    entry = {"operationId": operation_id, "tags": [module], "summary": action, "description": description, "security": security, "parameters": parameters, "responses": responses, "x-tela": screen, "x-acao-frontend": action, "x-consumidor": "integracao" if tech else ("frontend-publico" if public else "frontend-interno"), "x-implementado": False, "x-permissoes": permission.split(), "x-idempotencia": "obrigatoria" if idempotency else "nao_aplicavel", "x-backend-resolve": list(steps)}
    if body:
        media = {"schema": ref(body)}
        entry["requestBody"] = {"required": True, "content": {"multipart/form-data" if multipart else "application/json": media}}
        if body == "UploadLote":
            entry["requestBody"]["content"]["multipart/form-data"]["encoding"] = {"metadados": {"contentType": "application/json"}}
    target.setdefault(path, {})[method] = entry
    PERMISSIONS.update(permission.split())
    if not tech:
        SCENARIOS.append({"id": operation_id, "tela": screen, "acao": action, "metodo": method.upper(), "rota": path, "chamadasPorAcao": 1, "backendResolve": list(steps)})
    return entry


