op("get", "/agenda", "Agenda e retomada", "Minha agenda e entrar em contato", "Carregar pendências, retornos e motivos", "Lista já contém pessoa, pedido, responsável, ETag do item e ações. Data filtra previstoEm. Faixas de contato são configuráveis, não envios automáticos. Atividades internas ou tentativa sem resposta não renovam contato efetivo.", result="Agenda", permission="agenda.ler", params=[*PAG, DATE, param("motivo", enum("Motivo operacional.", ["aguardando_equipe", "retorno_vencido", "primeiro_contato", "inatividade", "tentativa_sem_resposta"]), "Filtrar lista."), param("responsavelId", uid(), "Escopo autorizado.")])
