op("post", "/conversas/{id}/encerrar", "Caixa WhatsApp", "Workspace da conversa", "Encerrar atendimento da conversa", "Ação com motivo, independente de concluir protocolos. Preserva contexto; retorna workspace ou estado autorizado para atualizar a caixa.", body="Motivo", result="WorkspaceConversa", permission="conversas.editar", match=True, etag=True)
